steps.script:
var b = tree.root.find_child("DismissNudgeButton", true, false)
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return "dismissed"
return "absent"

var b = tree.root.find_child("ContinueButton", true, false)
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return str(TutorialManager.current_step_id())

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for g in d._groups:
	out.append(str(g.label) + ":" + str((g.models as Array).size()))
return ",".join(out)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append(str(a.get("weapon", "?")) + ":" + str((a.get("models", []) as Array).size()))
return ",".join(out)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var wl = d.get_node("Content/GroupsScroll/GroupsBox/Group1/Body/WeaponList")
var want = -1
for i in range(wl.item_count):
	if str(wl.get_item_text(i)).begins_with("Close combat weapon"):
		want = i
if want < 0:
	return "no Close combat weapon offered"
wl.select(want)
wl.item_selected.emit(want)
return "ok"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append(str(a.get("weapon", "?")) + ":" + str((a.get("models", []) as Array).size()))
return ",".join(out)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var spin = d.get_node("Content/GroupsScroll/GroupsBox/Group1/Body/SplitBox/SplitRow_choppa_melee/Count_choppa_melee")
spin.value = 5
return int(spin.value)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append(str(a.get("weapon", "?")) + ":" + str((a.get("models", []) as Array).size()))
return ",".join(out)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var seen = {}
for a in d.assignments:
	for m in a.get("models", []):
		if seen.has(str(m)):
			return "model " + str(m) + " assigned twice"
		seen[str(m)] = true
return str(seen.size())

var p = PhaseManager.get_current_phase_instance()
var out = []
for a in p.staged_fight_state["assignments"]:
	out.append(str(a.get("weapon", "?")) + ":" + str((a.get("models", []) as Array).size()))
return ",".join(out)
